def choose_move(observation):
    # Defensive defaults
    x = observation.get("player", {}).get("position", (0, 0))[0]
    y = observation.get("player", {}).get("position", (0, 0))[1]

    # Identify possible goals across modes defensively
    grid = observation.get("grid", [])
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    # Simple safety: stay within bounds
    dx = 0
    dy = 0

    # Prefer moving toward the nearest resource/target if detectable
    target = None
    best_dist = float("inf")

    # Check resources
    for rx, row in enumerate(grid):
        for cy, cell in enumerate(row):
            if cell == "R":  # resource
                dist = abs(rx - x) + abs(cy - y)
                if dist < best_dist:
                    best_dist = dist
                    target = (rx, cy)

    # If no resource, check enemies (pursuit_evasion)
    if target is None:
        for ex, row in enumerate(grid):
            for ey, cell in enumerate(row):
                if cell == "E":  # enemy
                    dist = abs(ex - x) + abs(ey - y)
                    if dist < best_dist:
                        best_dist = dist
                        target = (ex, ey)

    # If still no target, explore empty/territory
    if target is None:
        for gx, row in enumerate(grid):
            for gy, cell in enumerate(row):
                if cell == " " or cell == ".":
                    dist = abs(gx - x) + abs(gy - y)
                    if dist < best_dist:
                        best_dist = dist
                        target = (gx, gy)

    if target is not None:
        tx, ty = target
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        else:
            dx = 0

        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        else:
            dy = 0

        # Clip to -1,0,1 (defensive as required)
        dx = max(-1, min(1, dx))
        dy = max(-1, min(1, dy))

    return [dx, dy]

